import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"ADR-0059: Generic Object Key Evaluation","description":"","frontmatter":{},"headers":[],"relativePath":"handl/project/adrs/0059-generic-object-key-evaluation.md","filePath":"vendored/handl/project/adrs/0059-generic-object-key-evaluation.md"}`),a={name:`handl/project/adrs/0059-generic-object-key-evaluation.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0059-generic-object-key-evaluation" tabindex="-1">ADR-0059: Generic Object Key Evaluation <a class="header-anchor" href="#adr-0059-generic-object-key-evaluation" aria-label="Permalink to “ADR-0059: Generic Object Key Evaluation”">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><p>Proposed</p><p>Supersedes the per-engine hardcoded key handling introduced by <a href="./0052-arrow-calculus-kernel.html">ADR-0052 — Arrow Calculus Kernel</a> and extended by <a href="./0057-computed-object-keys.html">ADR-0057 — Computed Object Keys via Bracket Syntax</a>. Depends on the data-driven desugar pass from <a href="./0053-generic-pratt-parser.html">ADR-0053 — Generic Pratt Parser</a> §7 (<code>AstDesugarRule</code>).</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The <code>object</code> prim constructs an object value from entry nodes. Each entry has a key child and a value child. The key child can be:</p><ol><li>A <code>var</code> node — use the identifier name as the key string.</li><li>A <code>string</code> node — use the literal string.</li><li>An <code>array</code> node with one child — evaluate the inner expression and use its value&#39;s string representation (ADR-0057 computed bracket keys).</li><li>Any other node — evaluate it and use its value&#39;s string representation (the parenthesized <code>(expr):</code> form).</li></ol><p>This rule is implemented in <strong>Rust</strong> in each of the three eval engines (<code>plugin-engine-exec-tree-walk</code>, <code>plugin-engine-exec-bytecode</code>, <code>plugin-engine-exec-cranelift</code>). Adding a new key form (as ADR-0057 did) required changing all three engines in lockstep. This violates the platform&#39;s design principle: language rules should be <strong>data</strong>, not engine code (ADR-0053 §1, ADR-0052 §&quot;Why a kernel&quot;).</p><p>The desugar pass (ADR-0053 §7) already provides a data-driven <code>Ast → Ast</code> rewrite mechanism: an <code>AstShapeDef</code> with a <code>desugar</code> rule rewrites nodes of that kind into a <code>target_kind</code> with specified children, before evaluation. The <code>if → match</code> desugar is the canonical example. This pass runs once, between parse and eval, in <code>Runtime::parse</code> — all engines consume the desugared AST.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Move object-key resolution from the eval engines into the <strong>desugar pass</strong>, expressed as data.</p><h3 id="step-1-desugar-expr-entries-at-parse-time" tabindex="-1">Step 1: Desugar <code>[expr]:</code> entries at parse time <a class="header-anchor" href="#step-1-desugar-expr-entries-at-parse-time" aria-label="Permalink to “Step 1: Desugar [expr]: entries at parse time”">​</a></h3><p>Add a desugar rule on the <code>entry</code> AST shape that detects array-keyed entries and rewrites them into a canonical &quot;computed entry&quot; form before any engine sees them. The rewrite:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>entry { children: [array { children: [expr] }, value] }</span></span>
<span class="line"><span>  →  entry { children: [expr, value] }</span></span></code></pre></div><p>The array wrapper is stripped; the inner expression becomes the key child directly. After desugar, no entry&#39;s key child is ever an <code>array</code> node.</p><h3 id="step-2-simplify-the-engine-key-rule-to-two-cases" tabindex="-1">Step 2: Simplify the engine key rule to two cases <a class="header-anchor" href="#step-2-simplify-the-engine-key-rule-to-two-cases" aria-label="Permalink to “Step 2: Simplify the engine key rule to two cases”">​</a></h3><p>With array keys eliminated by desugar, each engine&#39;s <code>object</code> prim reduces to:</p><ul><li><strong><code>var</code> or <code>string</code></strong> — use the payload string directly (literal key).</li><li><strong>anything else</strong> — evaluate the expression and use its value&#39;s string representation (computed key).</li></ul><p>This is already the &quot;else&quot; branch that existed before ADR-0057. The <code>array</code>-key branch added by ADR-0057 is removed from all three engines.</p><h3 id="step-3-future-key-forms-are-desugar-rules-not-engine-changes" tabindex="-1">Step 3: Future key forms are desugar rules, not engine changes <a class="header-anchor" href="#step-3-future-key-forms-are-desugar-rules-not-engine-changes" aria-label="Permalink to “Step 3: Future key forms are desugar rules, not engine changes”">​</a></h3><p>Adding a new key form (e.g. template-literal keys, symbol keys) becomes a desugar rule on the <code>entry</code> shape in kit data — no engine code changes.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><strong>One rule, not three.</strong> The key-resolution logic lives in one desugar rule, not in three Rust engines. Adding or changing key forms is a data change to <code>ast.yaml</code>.</li><li><strong>Engines get simpler.</strong> Each engine&#39;s <code>object</code> prim drops the <code>array</code>-key branch (and eventually can drop the <code>var</code>/<code>string</code> special cases too, if those are also moved to desugar).</li><li><strong>No runtime cost.</strong> The desugar pass already runs between parse and eval; stripping an array wrapper is a single node rewrite, amortized once.</li><li><strong>ADR-0057&#39;s Rust changes become transitional.</strong> The per-engine <code>array</code>-key branches added by ADR-0057 are removed once the desugar rule is in place. ADR-0057&#39;s <em>language design</em> (bracket computed keys are valid) stands; its <em>implementation</em> is superseded.</li><li><strong>The parenthesized <code>(expr):</code> form needs no desugar</strong> — it already produces a <code>paren</code> node, which falls into the &quot;evaluate&quot; branch unchanged.</li></ul>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};